/**
 * purge-main-db-broken.mjs — Remove mapped entries whose targetUrl is not in
 * dist/sitemap*.xml (the single source of truth for "real routes").
 *
 * Why a dedicated script (vs. inline in check-keyword-map.mjs)?
 *   - data/keywords/main-db.json is the canonical entity-keyword registry
 *     consumed by src/lib/auto-inline-links.ts at runtime.
 *   - It is NOT regenerated by scripts/generate-internal-links.mjs (which only
 *     touches astro.config.mjs). So it needs its own purge to remove the
 *     fabricated targets that minimax previously wrote here.
 *
 * Safety:
 *   - Creates a timestamped backup (.bak-<date>) before any write.
 *   - Skips non-internal targets (http/mailto/tel/#) — they are not 404-prone.
 *   - Skips status !== 'mapped' — 'planned' entries are pre-launch seeds.
 *   - Writes a JSON report of purged ids to _audit/maindb-purge-report.json.
 *
 * Usage:
 *   node scripts/purge-main-db-broken.mjs
 *   node scripts/purge-main-db-broken.mjs --dry-run   # report only, no writes
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const DIST_DIR = path.join(ROOT, 'dist');
const DB_PATH = path.join(ROOT, 'data', 'keywords', 'main-db.json');
const REPORT_PATH = path.join(ROOT, '_audit', 'maindb-purge-report.json');

const SUPPORTED_LANGS = new Set([
  'de', 'ja', 'fr', 'es', 'pt', 'it', 'ko', 'nl', 'pl', 'ru', 'ar',
]);

function pullSitemapRoutes() {
  if (!fs.existsSync(DIST_DIR)) {
    throw new Error('dist/ not found. Run `npm run build` first.');
  }
  const files = fs.readdirSync(DIST_DIR).filter(f => /^sitemap.*\.xml$/.test(f));
  if (files.length === 0) {
    throw new Error('No sitemap*.xml found under dist/. Run `npm run build` first.');
  }
  const locRe = /<loc>([^<]+)<\/loc>/g;
  const hostRe = /^https?:\/\/[^/]+/;
  const routes = new Set();
  for (const f of files) {
    const text = fs.readFileSync(path.join(DIST_DIR, f), 'utf-8');
    for (const m of text.matchAll(locRe)) {
      routes.add(m[1].replace(hostRe, ''));
    }
  }
  return routes;
}

function isExternal(href) {
  return /^(https?:|mailto:|tel:|#)/.test(href);
}

function langOf(href) {
  const seg = href.replace(/^\//, '').split('/', 1)[0];
  return SUPPORTED_LANGS.has(seg) ? seg : 'en';
}

function main() {
  const dryRun = process.argv.includes('--dry-run');

  const routes = pullSitemapRoutes();
  console.log(`✓ Loaded ${routes.size} authoritative routes from dist/sitemap*.xml`);

  if (!fs.existsSync(DB_PATH)) {
    throw new Error(`main-db.json not found at ${DB_PATH}`);
  }
  const data = JSON.parse(fs.readFileSync(DB_PATH, 'utf-8'));
  console.log(`✓ Loaded ${data.length} entries from main-db.json`);

  const broken = [];
  const kept = [];
  for (const e of data) {
    const isMapped = e && e.status === 'mapped';
    const href = (e && e.targetUrl) || '';
    if (!isMapped || !href || isExternal(href)) {
      kept.push(e);
      continue;
    }
    const normalized = href.endsWith('/') ? href : href + '/';
    if (routes.has(normalized)) {
      kept.push(e);
    } else {
      broken.push({
        id: e.id || null,
        keyword: e.keyword || null,
        href,
        lang: e.lang || null,
        source: e.source || null,
        entity: e.entity || null,
      });
    }
  }

  console.log(`\n── Purged ${broken.length} broken mapped entries ──`);
  for (const b of broken.slice(0, 15)) {
    console.log(`  [${b.lang}] ${(b.keyword || b.id || '?').slice(0, 50)}  →  ${b.href}`);
  }
  if (broken.length > 15) {
    console.log(`  ... and ${broken.length - 15} more`);
  }

  // Always write the report (even on dry-run)
  fs.mkdirSync(path.dirname(REPORT_PATH), { recursive: true });
  fs.writeFileSync(REPORT_PATH, JSON.stringify({
    generatedAt: new Date().toISOString(),
    dryRun,
    routesCount: routes.size,
    beforeCount: data.length,
    afterCount: kept.length,
    purgedCount: broken.length,
    purged: broken,
  }, null, 2), 'utf-8');
  console.log(`\n→ Report: ${REPORT_PATH}`);

  if (dryRun) {
    console.log('\n(--dry-run: no files were modified.)');
    return;
  }

  if (broken.length === 0) {
    console.log('\n✓ No broken entries to purge.');
    return;
  }

  // Backup
  const date = new Date().toISOString().slice(0, 10);
  const backupPath = `${DB_PATH}.bak-${date}`;
  fs.copyFileSync(DB_PATH, backupPath);
  console.log(`✓ Backup: ${backupPath}`);

  // Write
  fs.writeFileSync(DB_PATH, JSON.stringify(kept, null, 2), 'utf-8');
  console.log(`✓ Wrote ${kept.length} entries (was ${data.length}) to main-db.json`);

  // Also update dist-data if present (some projects mirror data/ into dist/)
  const distMirror = path.join(ROOT, 'dist-data', 'keywords', 'main-db.json');
  if (fs.existsSync(distMirror)) {
    fs.copyFileSync(DB_PATH, distMirror);
    console.log(`✓ Synced dist mirror: ${distMirror}`);
  }
}

try {
  main();
} catch (err) {
  console.error(`\n✗ ERROR: ${err.message}`);
  process.exit(1);
}